{
  "diagnosis": "Both TX and RX serialize bits in reverse order. TX sends data_reg[DATA_WIDTH] first (MSB) instead of the LSB; RX shifts incoming bits left and appends at LSB, also yielding MSB-first. The start/stop bit logic and prescale*8 timing are otherwise correct, so only the bit ordering inside the frame needs fixing.",
  "edits": [
    {
      "file": "rtl/uart_tx.v",
      "start_line": 97,
      "end_line": 105,
      "replacement": "            if (input_axi_tvalid) begin\n                input_axi_tready_reg <= ~input_axi_tready_reg;\n                prescale_reg <= (prescale << 3)-1;\n                bit_cnt <= DATA_WIDTH+1;\n                data_reg <= {1'b1, input_axi_tdata};\n                txd_reg <= 0;\n                busy_reg <= 1;\n            end\n        end else begin\n            if (bit_cnt > 1) begin\n                bit_cnt <= bit_cnt - 1;\n                prescale_reg <= (prescale << 3)-1;\n                {data_reg, txd_reg} <= {data_reg[DATA_WIDTH-1:0], data_reg[DATA_WIDTH]};\n            end else if (bit_cnt == 1) begin"
    },
    {
      "file": "rtl/uart_rx.v",
      "start_line": 115,
      "end_line": 115,
      "replacement": "                data_reg <= {rxd, data_reg[DATA_WIDTH-1:1]};"
    }
  ]
}
